#!/usr/bin/env bash
# WARNING: Do not edit this file directly in your own repository.
# It is maintained in the grails-plugin-template repository.
# To make changes, edit it there and they will be synced automatically:
# https://github.com/grails-plugins/grails-plugin-template/tree/main/.github/scripts
#
# Runs a Groovy script in the official Groovy Docker image, so workflows need
# neither a JDK nor sdkman to run the scripts in .github/scripts. The Groovy
# version is independent of .sdkmanrc: the scripts only need Groovy and its
# bundled YAML module.
#
# Usage: .github/scripts/groovy.sh <script.groovy> [args...]
#
# The current directory is mounted at the same path, so relative and absolute
# paths into it keep working, and the script runs as the calling user, so files
# it writes stay owned by that user (and committable by the workflow).
#
# Environment:
#   GROOVY_IMAGE    overrides the image (default below)
#   GITHUB_TOKEN, GITHUB_REPOSITORY, GITHUB_OUTPUT, FILTER_PROJECT, VERIFY_STRICT
#                   passed through to the script when set
set -euo pipefail

image="${GROOVY_IMAGE:-groovy:5.0-jdk21}"

docker_args=(--rm --user "$(id -u):$(id -g)" -e HOME=/tmp -v "${PWD}:${PWD}" -w "${PWD}")
for var in GITHUB_TOKEN GITHUB_REPOSITORY GITHUB_OUTPUT FILTER_PROJECT VERIFY_STRICT; do
    if [ -n "${!var:-}" ]; then
        docker_args+=(-e "${var}")
    fi
done
# GITHUB_OUTPUT is a runner file outside the workspace
if [ -n "${GITHUB_OUTPUT:-}" ]; then
    docker_args+=(-v "${GITHUB_OUTPUT}:${GITHUB_OUTPUT}")
fi

exec docker run "${docker_args[@]}" "${image}" groovy "$@"
